import React, { useRef } from 'react';

const STRATEGY_LABELS = {
  Standard:      { uz: 'Oddiy narx',        emoji: '💰' },
  HappyHour:     { uz: 'Baxtli soat (-20%)', emoji: '🎉' },
  LoyaltyCard:   { uz: 'Doimiy mijoz',       emoji: '⭐' },
  GroupDiscount: { uz: 'Guruh chegirma',     emoji: '👥' },
};

function dashes(n = 40) { return '─'.repeat(n); }
function dots(n = 40)   { return '· · · · · · · · · · · · · · · · · · · ·'.slice(0, n); }

function padLine(left, right, total = 38) {
  const spaces = Math.max(1, total - left.length - right.length);
  return left + ' '.repeat(spaces) + right;
}

export default function ReceiptModal({ bill, table, onClose }) {
  const receiptRef = useRef();
  const now = new Date();
  const receiptNo = `BP-${now.getFullYear()}${String(now.getMonth()+1).padStart(2,'0')}${String(now.getDate()).padStart(2,'0')}-${bill.id.slice(0,6).toUpperCase()}`;
  const timeStr = now.toLocaleTimeString('uz-UZ', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
  const dateStr = now.toLocaleDateString('uz-UZ', { day: '2-digit', month: '2-digit', year: 'numeric' });
  const stratLabel = STRATEGY_LABELS[bill.strategyName] || { uz: bill.strategyName, emoji: '💳' };

  function handlePrint() {
    const printWin = window.open('', '_blank', 'width=400,height=700');
    printWin.document.write(`
      <html>
        <head>
          <title>BitePlate Chek #${receiptNo}</title>
          <style>
            @import url('https://fonts.googleapis.com/css2?family=Courier+Prime:wght@400;700&display=swap');
            * { margin: 0; padding: 0; box-sizing: border-box; }
            body {
              font-family: 'Courier Prime', 'Courier New', monospace;
              background: #fff;
              color: #000;
              font-size: 12px;
              padding: 16px;
              width: 300px;
            }
            .center { text-align: center; }
            .bold { font-weight: 700; }
            .sep { letter-spacing: 2px; }
            .large { font-size: 18px; }
            .xl { font-size: 22px; }
            pre { font-family: inherit; white-space: pre-wrap; }
          </style>
        </head>
        <body>
          ${receiptRef.current.innerHTML}
          <script>window.onload = () => { window.print(); window.close(); }<\/script>
        </body>
      </html>
    `);
    printWin.document.close();
  }

  const discount = bill.lineItems.find((l) => l.amount < 0);
  const itemLines = bill.lineItems.filter((l) => l.amount > 0);

  return (
    <div className="modal-backdrop" onClick={onClose}>
      <div
        className="bg-[#0a0d14] border border-white/[0.08] rounded-2xl p-6 w-full max-w-sm max-h-[95vh] overflow-y-auto shadow-2xl"
        onClick={(e) => e.stopPropagation()}
      >
        {/* App header */}
        <div className="flex items-center justify-between mb-5">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 rounded-xl bg-emerald-500/20 flex items-center justify-center text-lg">🧾</div>
            <div>
              <p className="text-white font-bold">To'lov cheki</p>
              <p className="text-gray-600 text-xs">Muvaffaqiyatli to'landi</p>
            </div>
          </div>
          <div className="flex gap-2">
            <button onClick={handlePrint} className="btn btn-sm btn-ghost text-xs">🖨️ Chop etish</button>
            <button onClick={onClose} className="text-gray-600 hover:text-gray-400 text-lg">✕</button>
          </div>
        </div>

        {/* THE RECEIPT — paper style */}
        <div
          ref={receiptRef}
          style={{
            fontFamily: "'Courier New', Courier, monospace",
            background: '#fafaf7',
            color: '#111',
            borderRadius: '4px',
            padding: '20px 18px',
            fontSize: '11.5px',
            lineHeight: '1.6',
            boxShadow: '0 4px 32px rgba(0,0,0,0.5)',
            position: 'relative',
          }}
        >
          {/* Torn top edge */}
          <div style={{
            position: 'absolute', top: 0, left: 0, right: 0, height: '8px',
            background: 'repeating-linear-gradient(90deg, #fafaf7 0px, #fafaf7 6px, #e5e5e0 6px, #e5e5e0 8px)',
          }} />

          {/* Logo / header */}
          <div style={{ textAlign: 'center', paddingTop: '8px', marginBottom: '8px' }}>
            <div style={{ fontSize: '22px', fontWeight: 'bold', letterSpacing: '3px' }}>BITEPLATE</div>
            <div style={{ fontSize: '10px', color: '#555', marginTop: '2px' }}>Smart Restoran Boshqaruv Tizimi</div>
            <div style={{ fontSize: '10px', color: '#555' }}>Tel: +998 71 200-00-00</div>
            <div style={{ fontSize: '10px', color: '#555' }}>Toshkent, Yunusobod tumani</div>
          </div>

          <div style={{ borderTop: '1px dashed #aaa', margin: '8px 0' }} />

          {/* Meta info */}
          <div style={{ fontSize: '11px', color: '#333' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <span>Sana:</span><span style={{ fontWeight: 'bold' }}>{dateStr}</span>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <span>Vaqt:</span><span style={{ fontWeight: 'bold' }}>{timeStr}</span>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <span>Stol:</span><span style={{ fontWeight: 'bold' }}>№ {table.id}</span>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <span>Mijoz:</span><span style={{ fontWeight: 'bold' }}>{table.customerName}</span>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <span>Chek №:</span><span style={{ fontWeight: 'bold', fontSize: '10px' }}>{receiptNo}</span>
            </div>
          </div>

          <div style={{ borderTop: '1px dashed #aaa', margin: '8px 0' }} />

          {/* Items */}
          <div style={{ fontWeight: 'bold', fontSize: '10px', color: '#555', marginBottom: '4px', letterSpacing: '1px' }}>
            BUYURTMA TARKIBI
          </div>
          {itemLines.map((item, i) => {
            // parse "Name xQty" format from description
            const match = item.description.match(/^(.+?)\s+x(\d+)$/);
            const name = match ? match[1] : item.description;
            const qty  = match ? match[2] : '1';
            return (
              <div key={i} style={{ marginBottom: '3px' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', fontWeight: '600' }}>
                  <span style={{ flex: 1, paddingRight: '6px', fontSize: '11.5px' }}>{name}</span>
                  <span style={{ whiteSpace: 'nowrap' }}>${item.amount.toFixed(2)}</span>
                </div>
                <div style={{ color: '#777', fontSize: '10px', paddingLeft: '4px' }}>
                  {qty} × ${(item.amount / parseInt(qty || 1)).toFixed(2)}
                </div>
              </div>
            );
          })}

          <div style={{ borderTop: '1px dashed #aaa', margin: '8px 0' }} />

          {/* Totals */}
          <div style={{ fontSize: '11.5px' }}>
            <ReceiptRow label="Jami (chegirmasiz)" value={`$${bill.lineItems.filter(l=>l.amount>0).reduce((s,l)=>s+l.amount,0).toFixed(2)}`} />
            {discount && (
              <ReceiptRow label={`Chegirma (${stratLabel.emoji} ${stratLabel.uz})`} value={`-$${Math.abs(discount.amount).toFixed(2)}`} valueStyle={{ color: '#c00' }} />
            )}
            <ReceiptRow label="Soliq (QQS 8%)" value={`$${bill.tax.toFixed(2)}`} />
            {bill.tip > 0 && (
              <ReceiptRow label="Chayqa (xizmat haqi)" value={`$${bill.tip.toFixed(2)}`} />
            )}
          </div>

          <div style={{ borderTop: '2px solid #222', borderBottom: '2px solid #222', margin: '8px 0', padding: '6px 0' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', fontWeight: 'bold', fontSize: '16px' }}>
              <span>JAMI TO'LOV:</span>
              <span>${bill.total.toFixed(2)}</span>
            </div>
          </div>

          {/* Split bill */}
          {bill.perGuest && bill.guestCount > 1 && (
            <div style={{ background: '#f0f0e8', borderRadius: '4px', padding: '6px 8px', marginBottom: '6px', fontSize: '11px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <span>Har bir kishi ({bill.guestCount} ta mehmon):</span>
                <span style={{ fontWeight: 'bold' }}>${bill.perGuest.toFixed(2)}</span>
              </div>
            </div>
          )}

          {/* Payment confirmed */}
          <div style={{ textAlign: 'center', margin: '10px 0 6px' }}>
            <div style={{
              display: 'inline-block',
              border: '1.5px solid #1a7a3a',
              borderRadius: '4px',
              padding: '4px 16px',
              color: '#1a7a3a',
              fontWeight: 'bold',
              fontSize: '12px',
              letterSpacing: '2px',
            }}>
              ✓ TO'LOV QABUL QILINDI
            </div>
          </div>

          <div style={{ borderTop: '1px dashed #aaa', margin: '8px 0' }} />

          {/* Fiscal info block */}
          <div style={{ fontSize: '10px', color: '#555', lineHeight: '1.7' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <span>Soliq to'lovchi kodi:</span><span>123456789</span>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <span>Fiskal apparati №:</span><span>FP-{bill.id.slice(0,8).toUpperCase()}</span>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <span>Tartib raqami:</span><span>{Math.floor(Math.random()*9000)+1000}</span>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <span>Narxlash usuli:</span><span>{stratLabel.uz}</span>
            </div>
          </div>

          <div style={{ borderTop: '1px dashed #aaa', margin: '8px 0' }} />

          {/* ASCII QR placeholder */}
          <div style={{ textAlign: 'center', fontSize: '9px', color: '#999', lineHeight: '1.3', fontFamily: 'monospace', margin: '4px 0 8px' }}>
            <div>█▀▀▀▀▀█ ▄ ▄ ▄ ▄ █▀▀▀▀▀█</div>
            <div>█ ███ █ ▀▄█ █▄▀ █ ███ █</div>
            <div>█ ▀▀▀ █ █▄▀▄█▀ █ ▀▀▀ █</div>
            <div>▀▀▀▀▀▀▀ █ ▄ █ ▄ ▀▀▀▀▀▀▀</div>
            <div>▄▀ ▀█▄▀ ▄▀▄▀▄ ▀█▄ ▄▀▄</div>
            <div>█▀▀▀▀▀█ ▀█▄▀█▀ █▀▀▀▀▀█</div>
            <div style={{ marginTop: '3px', fontSize: '8px' }}>tekshirish.biteplate.uz/{receiptNo}</div>
          </div>

          {/* Thank you */}
          <div style={{ textAlign: 'center', fontSize: '13px', fontWeight: 'bold', marginBottom: '2px' }}>
            *** RAHMAT! YANA KELING! ***
          </div>
          <div style={{ textAlign: 'center', fontSize: '10px', color: '#888' }}>
            Taomlarimiz sifatiga ishonchingiz komil
          </div>
          <div style={{ textAlign: 'center', fontSize: '9px', color: '#bbb', marginTop: '4px' }}>
            www.biteplate.uz • @biteplate_uz
          </div>

          {/* Torn bottom edge */}
          <div style={{
            position: 'relative', marginTop: '12px', height: '8px',
            background: 'repeating-linear-gradient(90deg, #fafaf7 0px, #fafaf7 6px, #e5e5e0 6px, #e5e5e0 8px)',
          }} />
        </div>

        {/* Close button */}
        <button onClick={onClose} className="btn btn-ghost w-full mt-4">
          Yopish
        </button>
      </div>
    </div>
  );
}

function ReceiptRow({ label, value, valueStyle = {} }) {
  return (
    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '2px' }}>
      <span style={{ color: '#444' }}>{label}</span>
      <span style={{ fontWeight: '600', ...valueStyle }}>{value}</span>
    </div>
  );
}
